mapper.select:
SELECT c.check_in_id AS checkInId, c.event_id AS eventId, c.session_id AS sessionId, s.name AS sessionName, c.audience_key AS audienceKey, c.registration_id AS registrationId, r.display_name AS displayName, r.mobile_phone AS mobilePhone, c.check_in_method AS checkInMethod, c.checked_in_at AS checkedInAt, c.checked_in_by AS checkedInBy, c.notes AS notes FROM crm_event_check_in c JOIN crm_event_session s ON s.session_id = c.session_id AND s.tenant_id = c.tenant_id LEFT JOIN crm_event_registration r ON r.registration_id = c.registration_id WHERE c.tenant_id = #{tenantId} AND c.event_id = #{eventId}
AND c.session_id = #{query.sessionId}
AND (r.display_name ILIKE CONCAT('%', #{query.keyword}, '%') OR r.mobile_phone ILIKE CONCAT('%', #{query.keyword}, '%') OR c.audience_key ILIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY c.checked_in_at DESC
